effect.shader:
const float PI = 3.14159265;
void main() {
    vec4 o = texture(inputImg, acScreenNorm);
    if (comprimento <= 0.0) { fragColor = o; return; }
    int n = clamp(int(samples), 4, 48);
    float a = angle * PI / 180.0;
    vec2 d = vec2(cos(a), sin(a));
    d.x /= max(acAspect, 1e-4);

    vec4 soma = vec4(0.0);
    float peso = 0.0;
    for (int i = 0; i <= 48; i++) {
        if (i > n) break;
        float t = float(i) / float(n);
        float w = pow(1.0 - t, falloff);
        vec2 uv = acScreenNorm - d * comprimento * t;
        soma += texture(inputImg, uv) * w;
        peso += w;
    }
    fragColor = soma / max(peso, 1e-4);
}
